CREATE OR REPLACE VIEW `view_nettoanwesenheit` AS
select `b`.`PersNr` AS `personalnummer`,`p`.`name` AS `Name, Vorname`,if(`p`.`eg` = 'ZAK','ZAK','DPW') AS `Zuordnung ZAK/Eigen`,case when `k`.`kategorie` in ('operativ','leitstand','trainer') then 'gewerblich' when `k`.`kategorie` in ('Schichtleiter','Teamleiter','Leitung (AT)') then 'führungskraft' when `k`.`kategorie` = 'Admin' then 'kaufmännisch' end AS `Zuordnung kfm/gew/FK`,`p`.`taetigkeit` AS `Funktion`,`p`.`pdl` AS `Arbeitgeber`,`a`.`erklaerung` AS `Schichtmodell`,`p`.`oe` AS `Abteilung`,`b`.`Kommen` AS `erster Buchungszeitunkt`,max(`b2`.`datum`) AS `letzter Buchungszeitunkt`,NULL AS `Kostenstelle ZEUS` from ((((`tbl_ueb_fz_buchungen` `b` left join `tbl_ueb_personalakte_scd` `p` on(`b`.`PersNr` = `p`.`persnr` and `b`.`Datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`)) left join `tbl_stamm_kategorie_abteilung` `k` on(`p`.`taetigkeit` = `k`.`tätigkeit`)) left join `tbl_abwesenheitsgrund` `a` on(`b`.`tp` = `a`.`kuerzel` and `a`.`feld` = 'Tagesplan')) left join `tbl_import_buchungen_mitarbeiter` `b2` on(`b2`.`pers_nr` = `b`.`PersNr` and cast(`b2`.`datum` as date) = `b`.`Datum` and `b2`.`bg` = 'Ge')) where `b`.`Datum` between curdate() - interval 14 day and curdate() group by `b`.`PersNr`,`b`.`Datum`;
